<script setup>
import { reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { api, errorMessage } from '../api.js'
import { browserZone } from '../time.js'
const form = reactive({ displayName: '', email: '', password: '', timeZone: browserZone() }), confirmPassword = ref(''), busy = ref(false), error = ref(''), router = useRouter()
async function submit() { if (form.password !== confirmPassword.value) { error.value = 'Passwords do not match.'; return } busy.value = true; error.value = ''; try { await api.post('/auth/register', form); router.push('/login?registered=1') } catch (e) { error.value = errorMessage(e) } finally { busy.value = false } }
</script>
<template><div class="auth-page"><section class="auth-art"><RouterLink class="brand" to="/login"><span class="brand-mark">s•</span>smartreminder</RouterLink><div><span class="eyebrow">A FRESH START</span><h1>Remember less.<br><em>Enjoy more.</em></h1><p>One place for thoughtful reminders, reliable email notifications, and a clear history of every attempt.</p></div><small>YOUR TIME, WELL LOOKED AFTER.</small></section><section class="auth-form-wrap"><form class="auth-form" @submit.prevent="submit"><span class="eyebrow purple">MAKE YOURSELF AT HOME</span><h2>Create your workspace.</h2><p class="muted">A few details, and you’re ready to begin.</p><p v-if="error" class="notice error" role="alert">{{ error }}</p><label>Your name<input v-model.trim="form.displayName" required maxlength="100" autocomplete="name" placeholder="Your name"></label><label>Email address<input v-model.trim="form.email" type="email" required maxlength="254" autocomplete="username" placeholder="you@example.com"></label><div class="form-grid"><label>Password<input v-model="form.password" type="password" required minlength="8" maxlength="72" autocomplete="new-password"></label><label>Confirm password<input v-model="confirmPassword" type="password" required autocomplete="new-password"></label></div><small class="field-help">Use at least 8 characters; maximum 72 UTF-8 bytes.</small><label>Time zone<input v-model.trim="form.timeZone" required maxlength="64" placeholder="Asia/Kolkata"></label><button class="button primary full" :disabled="busy">{{ busy ? 'Creating account…' : 'Create account →' }}</button><p class="auth-switch">Already registered? <RouterLink to="/login">Sign in</RouterLink></p></form></section></div></template>
